import React, { useState, useEffect } from 'react';
// Google Yapay Zeka Kütüphanesi
import { GoogleGenerativeAI } from "@google/generative-ai";

function App() {
  // ⚠️ 1. API KEY'İ BURAYA YAPIŞTIR
  const API_KEY = "AIzaSyAycjPVxkbcJFfOSJyTp8oBUsONgK7lY1k"; 

  // --- STATE YÖNETİMİ ---
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]); // Rota listemiz
  const [filtre, setFiltre] = useState('Hepsi');
  const [maxSure, setMaxSure] = useState('');

  // Pencerelerin Kontrolü
  const [seciliMekan, setSeciliMekan] = useState(null); 
  const [listeAcik, setListeAcik] = useState(false);

  // AI Cevapları
  const [aiCevap, setAiCevap] = useState("");
  const [aiYukleniyor, setAiYukleniyor] = useState(false);
  const [aiDil, setAiDil] = useState("Türkçe");

  // Verileri Çek
  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => setMekanlar(Array.isArray(data) ? data : []))
      .catch(err => console.error("Bağlantı Hatası:", err));
  }, []);

  // --- YAPAY ZEKA FONKSİYONU ---
  const yapayZekayaSor = async (mekanAdi, bolge) => {
    if (!API_KEY || API_KEY.includes("BURAYA")) {
      setAiCevap("⚠️ Lütfen kodun içine geçerli bir API Anahtarı yapıştırın.");
      return;
    }
    setAiYukleniyor(true);
    setAiCevap(""); 
    try {
      const genAI = new GoogleGenerativeAI(API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-pro"});
      const prompt = `Sen Antalya turist rehberisin. "${mekanAdi}" (${bolge}) hakkında ${aiDil} dilinde, turistler için 3 cümlelik çok eğlenceli ve ilgi çekici bir tanıtım yaz. Emoji kullan.`;
      const result = await model.generateContent(prompt);
      const response = await result.response;
      setAiCevap(response.text());
    } catch (error) {
      setAiCevap("😔 Bağlantı hatası. Tekrar dene.");
    } finally {
      setAiYukleniyor(false);
    }
  };

  // --- ROTA EKLE / ÇIKAR (HATANIN DÜZELDİĞİ YER) ---
  // Artık hem 'e' (tıklama olayı) hem 'mekan' parametresini alıyor
  const favoriEkleCikar = (e, mekan) => {
    // Eğer e varsa durdur, yoksa devam et (Güvenlik önlemi)
    if(e && e.stopPropagation) e.stopPropagation(); 

    setFavoriler((mevcutListe) => {
      // Liste boş gelirse hata vermemesi için kontrol
      const aktifListe = Array.isArray(mevcutListe) ? mevcutListe : [];

      const varMi = aktifListe.some(item => item.id === mekan.id);

      if (varMi) {
        return aktifListe.filter(item => item.id !== mekan.id);
      } else {
        return [...aktifListe, { ...mekan, sure: Number(mekan.sure) || 0 }];
      }
    });
  };

  // --- TOPLAM SÜRE HESAPLAMA ---
  const toplamSure = favoriler.reduce((toplam, mekan) => toplam + (Number(mekan.sure) || 0), 0);
  const saat = Math.floor(toplamSure / 60);
  const dakika = toplamSure % 60;

  // Filtreleme
  const filtrelenmis = mekanlar.filter(m => {
    const katUygun = filtre === 'Hepsi' || m.kategori === filtre;
    const sureUygun = maxSure === '' || (Number(m.sure) || 0) <= Number(maxSure);
    return katUygun && sureUygun;
  });

  return (
    <div className="container">
      {/* --- CSS (GÖMÜLÜ) --- */}
      <style>{`
        body { font-family: 'Poppins', sans-serif; background-color: #f8f9fa; margin: 0; padding: 20px; }
        .header { text-align: center; margin-bottom: 30px; color: #1a4d6e; }
        .controls { display: flex; justify-content: center; gap: 10px; margin-bottom: 25px; flex-wrap: wrap; }

        .summary-bar { 
          background: #1a4d6e; color: white; padding: 15px 30px; 
          border-radius: 50px; display: flex; justify-content: space-around; 
          margin-bottom: 30px; font-weight: 600; cursor: pointer; user-select: none;
          box-shadow: 0 4px 15px rgba(26, 77, 110, 0.3); transition: transform 0.2s;
        }
        .summary-bar:hover { transform: scale(1.02); background: #153e5c; }

        .grid { display: flex; flex-wrap: wrap; justify-content: center; gap: 25px; }

        .card { width: 280px; background: white; border-radius: 20px; overflow: hidden; box-shadow: 0 5px 15px rgba(0,0,0,0.05); cursor: pointer; display: flex; flex-direction: column; transition: all 0.3s ease; border: 2px solid transparent; box-sizing: border-box; }
        .card:hover { transform: translateY(-5px); border-color: #00c2cb; box-shadow: 0 10px 25px rgba(0, 194, 203, 0.15); }
        .card-image-container { height: 180px; position: relative; padding: 10px; }
        .card-img { width: 100%; height: 100%; object-fit: cover; border-radius: 15px; }
        .badge { position: absolute; top: 15px; right: 15px; background: rgba(0,0,0,0.6); color: white; padding: 4px 10px; border-radius: 8px; font-size: 11px; backdrop-filter: blur(4px); }
        .card-content { padding: 15px; flex-grow: 1; display: flex; flex-direction: column; justify-content: space-between; }

        .btn-action { width: 100%; padding: 10px; border-radius: 20px; border: 1px solid #1a4d6e; background: transparent; color: #1a4d6e; font-weight: 600; cursor: pointer; margin-top: 10px; transition: all 0.3s; display: flex; justify-content: center; align-items: center; gap: 5px; }
        .btn-action:hover { background: #1a4d6e; color: white; }
        .btn-remove { border-color: #e74c3c; color: #e74c3c; }
        .btn-remove:hover { background: #e74c3c; color: white; }

        .modal-overlay { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.8); z-index: 1000; display: flex; justify-content: center; align-items: center; animation: fadeIn 0.3s; }
        .modal-content { background: white; padding: 25px; border-radius: 20px; max-width: 500px; width: 90%; position: relative; text-align: center; animation: slideUp 0.3s; max-height: 90vh; overflow-y: auto; }
        .close-btn { position: absolute; top: 15px; right: 15px; background: #f1f1f1; border: none; width: 30px; height: 30px; border-radius: 50%; cursor: pointer; font-weight: bold; }

        .ai-box { margin-top: 20px; background: #f0fdfa; padding: 15px; border-radius: 15px; border: 1px dashed #00c2cb; text-align: left; }
        .ai-controls { display: flex; gap: 10px; justify-content: center; margin-top: 15px; }
        .lang-select { padding: 8px; border-radius: 10px; border: 1px solid #ddd; }
        .btn-ai { background: linear-gradient(45deg, #00c2cb, #1a4d6e); color: white; border: none; padding: 8px 20px; border-radius: 10px; cursor: pointer; font-weight: bold; }
        .loading-spinner { border: 3px solid #f3f3f3; border-top: 3px solid #00c2cb; border-radius: 50%; width: 20px; height: 20px; animation: spin 1s linear infinite; }
        @keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes slideUp { from { transform: translateY(20px); } to { transform: translateY(0); } }
      `}</style>

      <div className="header">
        <h1>🌴 Antalya Rota Asistanı</h1>
      </div>

      <div className="controls">
        <input type="number" className="search-input" placeholder="Maks. Süre (dk)" value={maxSure} onChange={(e) => setMaxSure(e.target.value)} style={{padding: '10px 20px', borderRadius: '25px', border: '1px solid #ddd', outline: 'none'}} />
        {['Hepsi', 'Tarih', 'Doğa', 'Yemek', 'Eğlence'].map(k => (
          <button key={k} onClick={() => setFiltre(k)} style={{padding: '8px 20px', borderRadius: '25px', border: 'none', cursor: 'pointer', background: filtre === k ? '#1a4d6e' : 'white', color: filtre === k ? 'white' : '#666', boxShadow: '0 2px 5px rgba(0,0,0,0.05)'}}>{k}</button>
        ))}
      </div>

      <div className="summary-bar" onClick={() => setListeAcik(true)} title="Listeyi Gör">
        <span>🎒 Rotam: {favoriler.length} Yer</span>
        <span>⏱️ Toplam: {saat}sa {dakika}dk</span>
      </div>

      <div className="grid">
        {filtrelenmis.map(m => {
          // SeciliMi kontrolü güvenli hale getirildi
          const seciliMi = favoriler && favoriler.some(f => f.id === m.id);
          return (
            <div key={m.id} className="card" onClick={() => { setSeciliMekan(m); setAiCevap(""); }}>
              <div className="card-image-container">
                <img src={m.resim} alt={m.ad} className="card-img" />
                <span className="badge">{m.kategori}</span>
              </div>
              <div className="card-content">
                <h3 style={{margin: '0 0 5px 0', color: '#1a4d6e', fontSize: '16px'}}>{m.ad}</h3>
                <div style={{fontSize: '13px', color: '#7f8c8d', display: 'flex', justifyContent: 'space-between'}}>
                   <span>📍 {m.bolge}</span>
                   <span>⏳ {m.sure} dk</span>
                </div>
                {/* DOĞRU KULLANIM: (e) => favoriEkleCikar(e, m) */}
                <button className={`btn-action ${seciliMi ? 'btn-remove' : ''}`} onClick={(e) => favoriEkleCikar(e, m)}>
                  {seciliMi ? 'Rotadan Çıkar ✕' : 'Rotaya Ekle ➜'}
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {seciliMekan && (
        <div className="modal-overlay" onClick={() => setSeciliMekan(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="close-btn" onClick={() => setSeciliMekan(null)}>✕</button>
            <img src={seciliMekan.resim} alt={seciliMekan.ad} style={{width: '100%', borderRadius: '15px', height: '200px', objectFit: 'cover'}} />
            <h2 style={{color: '#1a4d6e', marginTop: '10px'}}>{seciliMekan.ad}</h2>
            <p style={{color: '#666'}}>Bölge: {seciliMekan.bolge} | Süre: {seciliMekan.sure} dk</p>

            <div className="ai-controls">
              <select className="lang-select" value={aiDil} onChange={(e) => setAiDil(e.target.value)}>
                <option value="Türkçe">🇹🇷 Türkçe</option>
                <option value="İngilizce">🇬🇧 English</option>
                <option value="Almanca">🇩🇪 Deutsch</option>
                <option value="Rusça">🇷🇺 Русский</option>
              </select>
              <button className="btn-ai" onClick={() => yapayZekayaSor(seciliMekan.ad, seciliMekan.bolge)} disabled={aiYukleniyor}>
                {aiYukleniyor ? <div className="loading-spinner"></div> : "🤖 AI'a Sor"}
              </button>
            </div>

            {aiCevap && (
              <div className="ai-box">
                <h4 style={{margin: '0 0 5px 0', color: '#00c2cb'}}>🤖 Asistan:</h4>
                <p style={{fontSize: '14px', color: '#555', lineHeight: '1.5'}}>{aiCevap}</p>
              </div>
            )}
          </div>
        </div>
      )}

      {listeAcik && (
        <div className="modal-overlay" onClick={() => setListeAcik(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="close-btn" onClick={() => setListeAcik(false)}>✕</button>
            <h3 style={{color: '#1a4d6e', borderBottom: '2px solid #eee', paddingBottom: '10px'}}>🎒 Senin Rotan</h3>
            <div style={{maxHeight: '300px', overflowY: 'auto', textAlign: 'left', marginTop: '10px'}}>
              {favoriler.length === 0 ? <p style={{color: '#999'}}>Listen boş.</p> : favoriler.map(fav => (
                <div key={fav.id} style={{padding: '10px', borderBottom: '1px solid #eee', display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}>
                  <div><strong>{fav.ad}</strong> <br/><span style={{fontSize:'12px', color:'#888'}}>{fav.bolge}</span></div>
                  <div style={{display:'flex', gap:'10px', alignItems:'center'}}>
                    <span style={{color: '#1a4d6e', fontWeight: 'bold'}}>{fav.sure} dk</span>
                    <button onClick={(e) => favoriEkleCikar(e, fav)} style={{border:'none', background:'#ffebee', color:'red', borderRadius:'50%', width:'25px', height:'25px', cursor:'pointer'}}>✕</button>
                  </div>
                </div>
              ))}
            </div>
            {favoriler.length > 0 && <div style={{marginTop: '15px', background: '#e8f5e9', padding: '10px', borderRadius: '10px', color: '#2e7d32', fontWeight: 'bold'}}>Toplam: {saat} sa {dakika} dk</div>}
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
